namespace CGMCollage;
using System.IO;
using SkiaSharp;
public static class SmokeTests
{
 public static int Run(string[] args){try{CollageTests.Run();if(Templates.Names.Length!=18)throw new Exception("Template count");foreach(var n in Templates.Names)if(Templates.Create(n).Count<2)throw new Exception(n);var p=new Project{Gap=12};var targeted=PanelPlacement.Plan(p,2,1);if(targeted.Count!=1||targeted[0]!=2)throw new Exception("Drop target was not preserved");using(var b=new SKBitmap(96,64)){using var c=new SKCanvas(b);c.Clear(new SKColor(236,31,83));using var paint=new SKPaint{Color=new SKColor(37,101,211)};c.DrawCircle(48,32,24,paint);using var image=SKImage.FromBitmap(b);using var data=image.Encode(SKEncodedImageFormat.Png,100);p.Frames[0].Image=new("smoke.png","image/png",Convert.ToBase64String(data.ToArray()));}p.Frames[0].Brightness=.12;p.Frames[0].Contrast=1.15;p.Frames[0].BorderWidth=4;var dir=args.SkipWhile(x=>x!="--smoke-test").Skip(1).FirstOrDefault()??Path.GetTempPath();Directory.CreateDirectory(dir);var project=Path.Combine(dir,"smoke.cgmcollage");ProjectIO.Save(project,p);var loaded=ProjectIO.Load(project);foreach(var ext in new[]{"png","jpg","webp"}){var output=Path.Combine(dir,$"smoke.{ext}");Renderer.Export(loaded,output);if(new FileInfo(output).Length<1000)throw new Exception($"{ext} export too small");}File.WriteAllText(Path.Combine(dir,"smoke-passed.txt"),"CGM Collage smoke test passed");return 0;}catch(Exception e){File.WriteAllText(Path.Combine(Path.GetTempPath(),"cgm-smoke-failed.txt"),e.ToString());return 1;}}
}
